<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';require_once __DIR__.'/../lib/notifications.php';send_cors_headers();$context=require_admin('influencers.manage');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->query('SELECT id,full_name,email,mobile,handle,status,verification_status,email_verified,platforms_json,audience_json,created_at FROM influencers ORDER BY created_at DESC LIMIT 300');json_response(200,['success'=>true,'influencers'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$id=trim((string)($body['influencer_id']??''));$action=trim((string)($body['action']??''));$reason=trim((string)($body['reason']??''));$next=['approve'=>'active','request_changes'=>'changes_requested','reject'=>'rejected','suspend'=>'suspended','reactivate'=>'active'][$action]??'';if($next===''||($action!=='approve'&&$action!=='reactivate'&&mb_strlen($reason)<10))json_response(422,['success'=>false,'message'=>'Valid decision and detailed reason are required.']);$stmt=$db->prepare('SELECT * FROM influencers WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$creator=$stmt->fetch();if(!$creator)json_response(404,['success'=>false,'message'=>'Creator not found.']);if(in_array($action,['approve','reactivate'],true)&&!(bool)$creator['email_verified'])json_response(409,['success'=>false,'message'=>'Verify the creator email before activating this account.']);if($action==='approve'){$review=$db->prepare('SELECT COUNT(DISTINCT d.document_type) FROM influencer_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.influencer_id=:id AND d.document_type IN ("identity","pan","social_ownership") AND d.verification_status="approved" AND f.scan_status="clean" AND f.deleted_at IS NULL');$review->execute(['id'=>$id]);if((int)$review->fetchColumn()<3||mb_strlen((string)$creator['bio'])<40)json_response(409,['success'=>false,'message'=>'Approve identity, PAN and social ownership documents and check the creator bio first.']);}$map=['pending_review'=>['active','changes_requested','rejected'],'changes_requested'=>['pending_review','rejected'],'active'=>['suspended'],'suspended'=>['active']];assert_transition($creator['status'],$next,$map);$verification=$next==='active'?'approved':($next==='changes_requested'?'changes_requested':($next==='rejected'?'rejected':$creator['verification_status']));$db->prepare('UPDATE influencers SET status=:status,verification_status=:verification,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'verification'=>$verification,'id'=>$id]);create_notification('influencer',$id,'application_update','Creator programme update','Your application/account is now '.str_replace('_',' ',$next).'.',null,['reason'=>$reason]);record_status_change('influencer',$id,$creator['status'],$next,$reason?:null);audit_event('admin.influencer_'.$action,'influencer',$id,['reason'=>$reason]);json_response(200,['success'=>true,'message'=>'Creator status updated.','status'=>$next]);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
